pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        // ensure the fuzzed nonOwner is not the deployer (who is the initial owner)
        vm.assume(nonOwner != address(this));
        // ensure nonOwner and newOwner are different from each other (so we can observe a change)
        vm.assume(newOwner != nonOwner);
        // ensure newOwner is not the initial owner either (to clearly observe a difference)
        vm.assume(newOwner != address(this));

        // record the original owner
        address originalOwner = c.owner();

        // a non-owner tries to change the owner
        vm.prank(nonOwner);
        c.setOwner(newOwner);

        // after the call, the owner must still be the original owner
        assertTrue(c.owner() == originalOwner);
    }
}

