pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Restrict to plausible addresses
        vm.assume(caller != address(0) && newOwner != address(0));
        vm.assume(caller != address(c));

        // Record the owner before the call
        address ownerBefore = c.owner();

        // Arbitrary caller attempts to change the owner
        vm.prank(caller);
        c.setOwner(newOwner);

        // The reference contract preserves the owner; the buggy one does not.
        // If caller is not the current owner, the reference reverts, so owner stays the same.
        // The mutant allows the change, so owner may differ.
        assertEq(c.owner(), ownerBefore, "Owner changed unexpectedly");
    }
}

