pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure caller is not the current owner (msg.sender of setUp is this contract, which is the owner)
        vm.assume(caller != address(this));
        // Ensure newOwner is not the same as caller (to avoid a trivial pass)
        vm.assume(newOwner != caller);

        bool success;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool ret) {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(!success);
    }
}

