pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // Owner is the deployer of c (this contract). Only the current owner can call setOwner without revert.
        // We prank the current owner (address(this)) to ensure the call does not revert.
        vm.prank(address(this));
        // Drive the external entry point setOwner with a fuzzed newOwner address.
        // The call succeeds (does not revert) because msg.sender is owner.
        bool ret = c.setOwner(newOwner);
        // The reference always returns true; the buggy version returns false.
        assertTrue(ret);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // Owner is the EOA that deployed c in setUp (this contract).
        // We allow any _owner, including zero or the current owner.
        // The onlyOwner modifier already guards the call, so for a non-owner
        // sender the call reverts and we skip assertion (the rule holds vacuously).
        vm.prank(address(this));
        try c.setOwner(_owner) returns (bool) {
            // If the call succeeded, the new owner MUST equal _owner.
            assertEq(c.owner(), _owner);
        } catch {
            // Revert means the call didn't complete, so no state change assertion needed.
        }
    }
}
